 ['Time',['cycles','change','mortality'],'Patterns of sequence, duration, and change.'],['Space',['creation','scale','form'],'Possibility, creation, physical space, and the vast.'],['Light',['knowledge','fortune','attention'],'Visibility, information, relevance, and fortune.'],['Void',['absence','secrets','obscurity'],'What is hidden, absent, or difficult to know.'],['Heart',['identity','self','emotion'],'Individuality, soul, and personal feeling.'],['Mind',['choices','reason','consequence'],'Decisions, logic, and branching outcomes.'],['Rage',['belief','fear','conviction'],'Belief, intensity, fear, and the power of conviction.'],['Hope',['belief','possibility','faith'],'Faith, possibility, and what people choose to believe.'],['Life',['growth','health','abundance'],'Vitality, growth, and abundance.'],['Doom',['limits','fate','sacrifice'],'Limits, inevitability, and the cost of survival.'],['Breath',['freedom','movement','wind'],'Movement, freedom, and independence.'],['Blood',['bonds','community','duty'],'Relationships, loyalty, and collective responsibility.']
].map(([name,keywords,description])=>({id:name.toLowerCase(),name,keywords,description,status:'Thematic guide; not an exhaustive mechanical definition.'}));
const TONES=['Adventurous','Mysterious','Eerie','Whimsical','Dangerous'];
const SETTINGS={
 environment:[['glass deserts','salt flats crossed by mirrored ravines'],['submerged forests','deep water threaded with luminous roots'],['wind-carved mesas','high plateaus linked by rope bridges'],['ashen wetlands','black reeds and warm, mineral pools'],['crystal caverns','faceted chambers beneath a cold plain'],['floating orchards','islands drifting through a cloud ocean'],['basalt coast','tidal shelves beneath a storm-dark sky'],['fossil prairie','grasslands sprouting from colossal bones'],['snowbound terraces','stepped valleys under an aurora'],['moss-covered ruins','old stone cities reclaimed by vines'],['copper badlands','red gullies with singing metal seams'],['twilight marsh','a lowland veiled in violet mist']],
