+function generate(config){const seed=config.seed||`SB-${Date.now().toString(36).toUpperCase()}`,r=rng(seed),n=+config.count,inputs=config.mode==='guided'?config.guided:[];const names=new Set(),titles=new Set();
  const players=Array.from({length:n},(_,i)=>{let g=inputs[i]||{},name=g.name||`${pick(r,FIRST_NAMES)} ${pick(r,LAST_NAMES)}`;while(names.has(name))name+=` ${i+1}`;names.add(name);let cls=g.class||pick(r,CLASSES),aspect=g.aspect||pick(r,ASPECTS),title=`${cls} of ${aspect}`;if(config.uniqueTitles){let tries=0;while(titles.has(title)&&tries++<30){if(!g.class)cls=pick(r,CLASSES);if(!g.aspect)aspect=pick(r,ASPECTS);title=`${cls} of ${aspect}`}}titles.add(title);return{id:idFor(seed,'player',i),name,className:cls,aspect,title,dreamMoon:g.moon||pick(r,['Prospit','Derse']),serverIndex:g.server!==''&&g.server!==undefined?+g.server:null,entryOrder:0,serverId:null,clientIds:[],landId:idFor(seed,'land',i),spriteId:idFor(seed,'sprite',i),generationLog:[g.name?'Name fixed by creator':'Name generated',g.class||g.aspect?'Classpect partly constrained':'Classpect generated',g.moon?'Dream moon fixed by creator':'Dream moon generated']}});
  // Fixed server links are constraints: reject self-links and cycles, then topologically order them.
  const indegree=players.map(()=>0),edges=players.map(()=>[]);players.forEach((p,i)=>{if(p.serverIndex!==null){if(p.serverIndex===i)throw new Error(`${p.name} cannot be their own server.`);edges[p.serverIndex].push(i);indegree[i]++}});
  const ready=players.map((_,i)=>i).filter(i=>!indegree[i]),order=[];while(ready.length){const at=Math.floor(r()*ready.length),i=ready.splice(at,1)[0];order.push(i);edges[i].forEach(j=>{if(--indegree[j]===0)ready.push(j)})}if(order.length!==n)throw new Error('Guided server links create an entry dependency cycle. Change one or more server choices.');

