function playersHtml(){return `<div class="panel-title"><span>SESSION PLAYERS</span><em>${session.players.length} TITLES · ${esc(session.seed)}</em></div><div class="player-grid">${session.players.map(p=>{const sprite=session.sprites.find(x=>x.id===p.spriteId),land=session.lands.find(x=>x.id===p.landId);return `<article class="player-card"><div class="player-card-top"><span class="entry-num">${String(p.entryOrder).padStart(2,'0')}</span><span class="moon-badge">${esc(p.dreamMoon)}</span></div><h3>${esc(p.name)}</h3><div class="player-title">${esc(p.title)}</div><p class="player-aspect">${esc(p.aspect)} · thematic guide: ${esc(ASPECTS_INFO[p.aspect])}</p><div class="land-section"><b>SERVER / CLIENTS</b><p>${p.serverId?`Server: ${esc(playerBy(p.serverId).name)}`:'Initial host / no server'}${p.clientIds.length?` · Clients: ${p.clientIds.map(id=>esc(playerBy(id).name)).join(', ')}`:''}</p></div><div class="land-section"><b>KERNELSPRITE · ${esc(sprite.prototyping[0].input)}</b><p>${esc(sprite.description)}</p><p><b>Persistent tags:</b> ${sprite.tags.map(esc).join(', ')}.</p><p class="note">Second prototype planned: ${esc(sprite.prototyping[1].input)}. Consequences are descriptive implementation rules.</p></div><div class="land-section"><b>LAND</b><p>${esc(land.name)} · ${esc(land.environment)}</p></div><p class="note">${p.generationLog.map(esc).join(' · ')}</p></article>`}).join('')}</div>`}
